export function rememberScan(
  tx: SqlTransaction,
  workflow: string,
  key: string,
  successful: boolean,
) {
  const now = Date.now();
  tx.exec(
    "INSERT INTO scans (workflow, key, checked_at, successful_at) VALUES (?, ?, ?, ?) ON CONFLICT(workflow, key) DO UPDATE SET checked_at = excluded.checked_at, successful_at = CASE WHEN ? THEN excluded.successful_at ELSE scans.successful_at END",
    workflow,
    key,
    now,
    successful ? now : 0,
    successful ? 1 : 0,
  );
}
/** Inventory changes retire removed resources; an empty authorized inventory is a completed scan. */
export function retainScans(
  ctx: MutationContext<typeof requirements>,
  workflow: string,
  keys: string[],
) {
  controls(ctx);
  ctx.sql.transaction((tx) => {
    tx.exec(
      `DELETE FROM scans WHERE workflow = ? AND key NOT IN (${keys.map(() => "?").join(",") || "?"})`,
      workflow,
      ...(keys.length ? keys : [""]),
    );
    if (!keys.length) rememberScan(tx, workflow, "", true);
  });
}

import type { MutationContext, QueryContext, SqlTransaction } from "apps";
import { requirements } from "./installation.ts";
import { emptyCheckpoint, type Checkpoint } from "./types.ts";
type Reader = QueryContext<typeof requirements> | MutationContext<typeof requirements>;
type Writer = MutationContext<typeof requirements>;
export function controls(ctx: Reader) {
  const row = ctx.sql
    .exec<{
      owner: string | null;
      configuration_revision: string;
      delivery_enabled: number;
      configured_at: number;
    }>(
      "SELECT owner, configuration_revision, delivery_enabled, configured_at FROM controls WHERE id = 1",
    )
    .one();
  if (row.owner === null || row.owner !== ctx.user.id)
    throw new Error("Configure an unshared private copy as its owner first.");
  return row;
}
export function read(ctx: Reader, key: string): Checkpoint {
  const row = ctx.sql
    .exec<{ state: string }>("SELECT state FROM checkpoints WHERE key = ?", key)
    .toArray()[0];
  return row === undefined ? emptyCheckpoint() : JSON.parse(row.state);
}
export function write(
  ctx: Writer,
  key: string,
  update: (current: Checkpoint, tx: SqlTransaction) => Checkpoint,
) {
  controls(ctx);
  return ctx.sql.transaction((tx) => {
    const row = tx
      .exec<{ state: string }>("SELECT state FROM checkpoints WHERE key = ?", key)
      .toArray()[0];
    const before: Checkpoint = row === undefined ? emptyCheckpoint() : JSON.parse(row.state);
    const after = update(before, tx);
    tx.exec(
      "INSERT INTO checkpoints (key, revision, state) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET revision = excluded.revision, state = excluded.state",
      key,
      after.revision,
      JSON.stringify(after),
    );
    return after;
  });
}

