import type { Checkpoint, Observation } from "../common/types.ts";
const fact = (
  cursor: string,
  at: number,
  code: string,
  verdict: Observation["verdict"],
  failures = 0,
  successes = 0,
  since = at,
): Observation => ({ cursor, at, code, verdict, failures, successes, since });
export function availabilityObservation(
  at: number,
  status: "healthy" | "failed" | "unknown",
  previous: Checkpoint,
) {
  const failures = status === "failed" ? previous.observation.failures + 1 : 0;
  const successes = status === "healthy" ? previous.observation.successes + 1 : 0;
  return fact(
    `availability:${at}`,
    at,
    status === "unknown" ? "availability-unknown" : "availability",
    failures >= 3 ? "action" : successes >= 3 ? "healthy" : "unknown",
    failures,
    successes,
  );
}
export interface RuntimeFact {
  at: number;
  boot: string;
  startedAt: number;
  ready: boolean;
  unexpectedBoots: number[];
}
export function runtimeObservation(current: RuntimeFact, previous: Checkpoint) {
  const boots = [...new Set(current.unexpectedBoots)].filter(
    (at) => at <= current.at && at > current.at - 15 * 60000,
  );
  const lastBoot = Math.max(
    previous.observation.lastUnexpectedAt ?? 0,
    ...current.unexpectedBoots.filter((at) => at <= current.at),
  );
  const flapping = boots.length >= 3;
  const wasFlapping = previous.open && previous.observation.flapping === true;
  const pastBudget = !current.ready && current.at - current.startedAt > 180000;
  const successful = current.ready && (!wasFlapping || current.at - lastBoot >= 30 * 60000);
  const firstSuccess = previous.observation.successes > 0 ? previous.observation.since : current.at;
  const count = successful
    ? previous.observation.successes +
      (current.at - previous.observation.at >= 60000
        ? 1
        : previous.observation.successes === 0
          ? 1
          : 0)
    : 0;
  const healthy = successful && count >= 2 && current.at - firstSuccess >= 60000;
  return {
    ...fact(
      `${current.boot}:${current.at}`,
      current.at,
      flapping || (wasFlapping && !healthy)
        ? "pool-flapping"
        : pastBudget
          ? "pool-startup-failed"
          : "runtime-readiness",
      flapping || pastBudget ? "action" : healthy ? "healthy" : "unknown",
      0,
      count,
      successful ? firstSuccess : current.at,
    ),
    lastUnexpectedAt: lastBoot,
    flapping: flapping || (wasFlapping && !healthy),
  };
}
export interface HttpBucket {
  start: number;
  requests: number;
  errors: number;
}
export function serviceErrorsObservation(at: number, buckets: HttpBucket[]) {
  const ordered = [...buckets].sort((a, b) => a.start - b.start).slice(-5);
  const valid =
    ordered.length === 5 &&
    ordered.every(
      (bucket, index) =>
        bucket.start % 60000 === 0 &&
        bucket.start + 60000 <= at &&
        bucket.start >= at - 7 * 60000 &&
        bucket.requests >= 20 &&
        bucket.errors >= 0 &&
        bucket.errors <= bucket.requests &&
        (index === 0 || bucket.start === ordered[index - 1]!.start + 60000),
    );
  const elevated =
    valid &&
    ordered.every((bucket) => bucket.errors >= 5 && bucket.errors / bucket.requests >= 0.05);
  const critical =
    elevated &&
    ordered.every((bucket) => bucket.errors >= 10 && bucket.errors / bucket.requests >= 0.2);
  const below =
    valid && ordered.every((bucket) => bucket.errors < 5 || bucket.errors / bucket.requests < 0.05);
  return fact(
    ordered.map((bucket) => String(bucket.start)).join(":") || `http-unknown:${at}`,
    at,
    critical ? "service-errors-critical" : "service-errors",
    elevated ? "action" : below ? "healthy" : "unknown",
  );
}
export function errorSpikeObservation(
  at: number,
  events: number,
  priorHour: number | null,
  previous: Checkpoint,
) {
  const threshold = priorHour === null ? 20 : Math.max(10, (3 * priorHour) / 12);
  const openingRate = previous.open ? (previous.observation.openingRate ?? threshold) : threshold;
  const low = events < openingRate / 2;
  const since = low ? (previous.observation.successes > 0 ? previous.observation.since : at) : at;
  const successes = low ? previous.observation.successes + 1 : 0;
  return {
    ...fact(
      `error-count:${at}`,
      at,
      "error-event-spike",
      events >= threshold ? "action" : low && at - since >= 15 * 60000 ? "healthy" : "unknown",
      0,
      successes,
      since,
    ),
    openingRate,
  };
}

import type { WorkflowStepContext } from "apps";
import { requirements } from "../common/installation.ts";
import { configuration } from "../common/configuration.ts";
import { api, instant, list, numeric, ReadUnavailable, record, text, tool } from "../common/api.ts";
import type { Checkpoint, Observation } from "../common/types.ts";
import {
  availabilityObservation,
  errorSpikeObservation,
  runtimeObservation,
  serviceErrorsObservation,
} from "./conditions.ts";
type Step = WorkflowStepContext<typeof requirements>;
const unknown = (at: number, code: string): Observation => ({
  cursor: `${code}:${at}`,
  at,
  code,
  verdict: "unknown",
  failures: 0,
  successes: 0,
  since: at,
});
export async function readRelease(step: Step): Promise<Observation> {
  const now = Date.now(),
    source = configuration.operator.release;
  if (source === null) return unknown(now, "release-source-unconfigured");
  try {
    const response = record(await tool(step, source));
    const runs = list(response?.workflow_runs)
      .map(record)
      .filter((run) => run?.workflow_id === source.workflowId && run.head_branch === source.branch)
      .sort((a, b) => (instant(b?.created_at) ?? 0) - (instant(a?.created_at) ?? 0));
    const run = runs[0],
      id = numeric(run?.id),
      attempt = numeric(run?.run_attempt),
      at = instant(run?.updated_at);
    if (
      !run ||
      id === undefined ||
      attempt === undefined ||
      at === undefined ||
      at > now ||
      run.status !== "completed"
    )
      return unknown(now, "release-not-terminal");
    const failed = ["failure", "timed_out", "action_required", "startup_failure"].includes(
      text(run.conclusion) ?? "",
    );
    const sha = text(run.head_sha);
    const evidenceUrl = /^[a-zA-Z0-9_.-]+\/[a-zA-Z0-9_.-]+$/.test(source.repository)
      ? `https://github.com/${source.repository}/actions/runs/${id}`
      : undefined;
    return {
      cursor: `release:${id}:${attempt}:${text(run.conclusion) ?? "unknown"}`,
      decision: `release:${id}:${attempt}`,
      at: now,
      sourceAt: at,
      ...(sha && /^[a-f0-9]{40,64}$/.test(sha) ? { attemptedSha: sha } : {}),
      ...(evidenceUrl === undefined ? {} : { evidenceUrl }),
      code: failed ? "production-release-failed" : "production-release",
      verdict: failed ? "action" : run.conclusion === "success" ? "healthy" : "unknown",
      failures: 0,
      successes: 0,
      since: at,
    };
  } catch {
    return unknown(now, "release-read-unavailable");
  }
}
export async function readAvailability(step: Step, previous: Checkpoint) {
  const now = Date.now(),
    source = configuration.operator.availability;
  if (source === null) return unknown(now, "availability-source-unconfigured");
  try {
    const url = new URL(source.publicUrl);
    if (url.protocol !== "https:" || url.username || url.password || url.search)
      return unknown(now, "public-read-unconfigured");
    const response = await step.fetch(url, {
      redirect: "manual",
      signal: AbortSignal.any([step.signal, AbortSignal.timeout(10000)]),
    });
    // A refused credential or quota does not establish an outage.
    if ([401, 403, 429].includes(response.status))
      return availabilityObservation(now, "unknown", previous);
    const publicOk = response.status === 200;
    const backend = record(await api(step, "GET", "inventory"));
    if (!Array.isArray(backend?.apps) || !Array.isArray(backend?.accounts))
      return availabilityObservation(now, "unknown", previous);
    return availabilityObservation(now, publicOk ? "healthy" : "failed", previous);
  } catch (error) {
    return availabilityObservation(
      now,
      error instanceof ReadUnavailable && error.status > 0 && error.status < 500
        ? "unknown"
        : "failed",
      previous,
    );
  }
}
/** These projections must come from a verified existing metrics query. Missing fields stay unknown. */
export async function readRuntime(step: Step, previous: Checkpoint) {
  const now = Date.now(),
    source = configuration.operator.runtime;
  if (source === null) return unknown(now, "runtime-metrics-unconfigured");
  try {
    const value = record(await tool(step, source)),
      at = instant(value?.at),
      startedAt = instant(value?.startedAt),
      boot = text(value?.boot);
    const boots = list(value?.unexpectedBoots).map(instant);
    if (
      !value ||
      at === undefined ||
      startedAt === undefined ||
      !boot ||
      !/^[a-zA-Z0-9_.:-]{1,128}$/.test(boot) ||
      typeof value.ready !== "boolean" ||
      value.excludesExpectedRestarts !== true ||
      !Array.isArray(value.unexpectedBoots) ||
      boots.some((at) => at === undefined) ||
      at > now ||
      now - at > 2 * 60000 ||
      startedAt > at
    )
      return unknown(now, "runtime-evidence-incomplete");
    return runtimeObservation(
      {
        at,
        startedAt,
        boot,
        ready: value.ready,
        unexpectedBoots: boots.filter((at): at is number => at !== undefined),
      },
      previous,
    );
  } catch {
    return unknown(now, "runtime-read-unavailable");
  }
}
export async function readServiceErrors(step: Step) {
  const now = Date.now(),
    source = configuration.operator.httpErrors;
  if (source === null) return unknown(now, "unsampled-http-denominator-unconfigured");
  try {
    const value = record(await tool(step, source));
    if (
      value?.production !== true ||
      value.unsampled !== true ||
      value.excludesExpectedRefusalsAndProbes !== true
    )
      return unknown(now, "http-denominator-incomplete");
    const buckets = list(value.buckets).map(record);
    if (
      buckets.some(
        (bucket) =>
          instant(bucket?.start) === undefined ||
          numeric(bucket?.requests) === undefined ||
          numeric(bucket?.errors) === undefined,
      )
    )
      return unknown(now, "http-buckets-incomplete");
    return serviceErrorsObservation(
      now,
      buckets.map((bucket) => ({
        start: instant(bucket?.start)!,
        requests: numeric(bucket?.requests)!,
        errors: numeric(bucket?.errors)!,
      })),
    );
  } catch {
    return unknown(now, "http-metrics-unavailable");
  }
}
export async function readErrorSpike(step: Step, previous: Checkpoint) {
  const now = Date.now(),
    source = configuration.operator.errorCounts;
  if (source === null) return unknown(now, "error-event-counts-unconfigured");
  try {
    const value = record(await tool(step, source)),
      at = instant(value?.at),
      events = numeric(value?.events),
      priorHour = value?.priorHour === null ? null : numeric(value?.priorHour);
    if (
      !value ||
      value.production !== true ||
      value.excludesFeedbackAndExpectedRefusals !== true ||
      value.intervalMs !== 5 * 60000 ||
      at === undefined ||
      at > now ||
      now - at > 5 * 60000 ||
      events === undefined ||
      events < 0 ||
      priorHour === undefined ||
      (priorHour !== null && priorHour < 0)
    )
      return unknown(now, "error-count-evidence-incomplete");
    return errorSpikeObservation(at, events, priorHour, previous);
  } catch {
    return unknown(now, "error-counts-unavailable");
  }
}
export { readWorkflowHealth } from "./workflow-health.ts";

export interface ExpectedScan {
  name: string;
  maximumAgeMinutes: number;
}
export interface ScanHealth {
  workflow: string;
  checkedAt: number;
  successfulAt: number;
  known: number;
}
export interface DeliveryState {
  status: string;
  at: number;
}
const deliveryFailed = (status: string) => status === "uncertain" || status === "refused";

/** Human waits do not prevent subsequent scans from refreshing these timestamps. */
export function workflowHealthCondition(
  now: number,
  configuredAt: number,
  expected: readonly ExpectedScan[],
  scans: readonly ScanHealth[],
  deliveries: readonly DeliveryState[],
  complete = true,
): "healthy" | "action" | "unknown" {
  if (
    deliveries.some(
      (value) =>
        deliveryFailed(value.status) ||
        (["claimed", "submitted"].includes(value.status) && now - value.at > 60000),
    )
  )
    return "action";
  if (!expected.length || configuredAt <= 0 || configuredAt > now) return "unknown";
  let unknown = !complete;
  for (const scan of expected) {
    const maximumAge = scan.maximumAgeMinutes * 60000;
    if (
      !scan.name ||
      !Number.isFinite(maximumAge) ||
      maximumAge < 60000 ||
      maximumAge > 7 * 86400000
    )
      return "unknown";
    const current = scans.find((value) => value.workflow === scan.name);
    const successfulAt = Math.max(configuredAt, current?.successfulAt ?? 0);
    if (successfulAt > now || (current?.checkedAt ?? 0) > now) return "unknown";
    if (now - successfulAt > maximumAge) return "action";
    if (!current || current.successfulAt < configuredAt || current.known !== 1) unknown = true;
  }
  return unknown ? "unknown" : "healthy";
}

import type { WorkflowStepContext } from "apps";
import { requirements } from "../common/installation.ts";
import { configuration } from "../common/configuration.ts";
import { numeric, record, text, tool } from "../common/api.ts";
import type { Observation } from "../common/types.ts";
import { workflowHealthCondition } from "./workflow-health-condition.ts";
type Step = WorkflowStepContext<typeof requirements>;
const observation = (at: number, verdict: Observation["verdict"], code: string): Observation => ({
  cursor: `workflow-health:${at}`,
  at,
  verdict,
  code,
  failures: 0,
  successes: 0,
  since: at,
});
export async function readWorkflowHealth(step: Step): Promise<Observation> {
  const now = Date.now();
  if (!configuration.operator.workflowApps.length)
    return observation(now, "unknown", "workflow-watch-unconfigured");
  let unknown = false;
  for (const watched of configuration.operator.workflowApps) {
    try {
      const health = record(
        await tool(step, { app: watched.app, tool: "deliveryHealth", input: {} }),
      );
      const configuredAt = numeric(health?.configuredAt);
      if (
        health?.current !== true ||
        configuredAt === undefined ||
        !Array.isArray(health.deliveries) ||
        !Array.isArray(health.scans)
      ) {
        unknown = true;
        continue;
      }
      const deliveries = health.deliveries.map((value) => {
        const delivery = record(value);
        return { status: text(delivery?.status) ?? "unknown", at: numeric(delivery?.at) ?? 0 };
      });
      const scans = health.scans.map((value) => {
        const scan = record(value);
        return {
          workflow: text(scan?.workflow) ?? "",
          checkedAt: numeric(scan?.checkedAt) ?? 0,
          successfulAt: numeric(scan?.successfulAt) ?? 0,
          known: numeric(scan?.known) ?? 0,
        };
      });
      const result = workflowHealthCondition(
        now,
        configuredAt,
        watched.workflows,
        scans,
        deliveries,
        health.complete === true && scans.length <= 1000,
      );
      if (result === "action") return observation(now, "action", "workflow-check-failed");
      unknown ||= result === "unknown";
    } catch {
      unknown = true;
    }
  }
  return observation(
    now,
    unknown ? "unknown" : "healthy",
    unknown ? "no-confirmed-scans" : "workflow-check-healthy",
  );
}

